import "dotenv/config";
import express from "express";
import path from "path";
import cors from "cors";
import { createServer as createViteServer } from "vite";
import fs from "fs";
import { initializeApp, App, cert } from "firebase-admin/app";
import { getAuth } from "firebase-admin/auth";

// Initialize Firebase Admin lazily
let firebaseAdminApp: App | null = null;
function getFirebaseAdmin() {
  if (!firebaseAdminApp) {
    try {
      const serviceAccountJson = process.env.FIREBASE_SERVICE_ACCOUNT_KEY;
      if (serviceAccountJson) {
        try {
          const serviceAccount = JSON.parse(serviceAccountJson);
          firebaseAdminApp = initializeApp({
            credential: cert(serviceAccount),
          });
        } catch (parseError) {
          console.error(
            "Invalid JSON in FIREBASE_SERVICE_ACCOUNT_KEY environment variable.",
            parseError,
          );
        }
      } else {
        // Fallback to application default credentials (works if hosted on GCP with same project)
        firebaseAdminApp = initializeApp();
      }
    } catch (error) {
      console.warn("Could not initialize Firebase Admin SDK.", error);
    }
  }
  return firebaseAdminApp;
}

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(cors());
  app.use(express.json());

  const baseUrl = process.env.VITE_BASE_URL || "/pustaka-digital/";
  const basePath = baseUrl.endsWith("/") ? baseUrl.slice(0, -1) : baseUrl;

  const apiRouter = express.Router();

  // Health check
  apiRouter.get("/health", (req, res) => {
    res.json({ status: "ok" });
  });

  // Update password endpoint
  apiRouter.post("/users/:uid/password", async (req, res) => {
    try {
      const { uid } = req.params;
      const { password } = req.body;

      if (!password || password.length < 6) {
        return res
          .status(400)
          .json({ error: "Password must be at least 6 characters long." });
      }

      const adminApp = getFirebaseAdmin();
      if (!adminApp) {
        return res
          .status(500)
          .json({ error: "Firebase Admin SDK is not initialized." });
      }

      await getAuth(adminApp).updateUser(uid, { password });
      res.json({ success: true, message: "Password updated successfully" });
    } catch (error: any) {
      console.error("Update password error:", error);
      let errorMessage = error.message;
      if (errorMessage?.includes("identitytoolkit.googleapis.com")) {
        errorMessage =
          "Konfigurasi Firebase Admin tidak valid. Tambahkan FIREBASE_SERVICE_ACCOUNT_KEY di Secrets (Environment Variables).";
      }
      res.status(500).json({ error: errorMessage });
    }
  });

  // Delete user endpoint
  apiRouter.post("/users/:uid/delete", async (req, res) => {
    try {
      const { uid } = req.params;

      const adminApp = getFirebaseAdmin();
      if (!adminApp) {
        return res
          .status(500)
          .json({ error: "Firebase Admin SDK is not initialized." });
      }

      await getAuth(adminApp).deleteUser(uid);
      res.json({ success: true, message: "User deleted successfully" });
    } catch (error: any) {
      console.error("Delete user error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Mount on all possible paths to guarantee match regardless of env var mismatch between build and runtime
  app.use("/api", apiRouter);
  app.use("/pustaka-digital/api", apiRouter);
  if (basePath && basePath !== "/pustaka-digital") {
    app.use(`${basePath}/api`, apiRouter);
  }

  // Redirect root to base URL if they differ
  app.get("/", (req, res, next) => {
    if (baseUrl !== "/" && req.path === "/") {
      return res.redirect(baseUrl);
    }
    next();
  });

  // Vite middleware for development
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    // Serve static files mapped to baseUrl
    if (baseUrl !== "/") {
      app.use(baseUrl, express.static(distPath));
    }
    app.use(express.static(distPath));

    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  // Catch 404s and return JSON instead of Express HTML fallback
  app.use((req, res, next) => {
    if (req.path.includes("/api/")) {
      res
        .status(404)
        .json({ error: `API Route not found: ${req.method} ${req.path}` });
    } else {
      next();
    }
  });

  // Global error handler to ensure API routes always return JSON instead of Express HTML fallback
  app.use(
    (
      err: any,
      req: express.Request,
      res: express.Response,
      next: express.NextFunction,
    ) => {
      console.error("Express global error handler caught:", err);
      if (res.headersSent) {
        return next(err);
      }
      res
        .status(err.status || 500)
        .json({ error: err.message || "Internal Server Error" });
    },
  );

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
